T = {}
for _k, _d in S.items():
    for _l, _v in _d.items():
        T.setdefault(_l, {})[_k] = _v

_state = {"lang": "en"}


def set_lang(lang):
    _state["lang"] = lang if lang in T else "en"


def cur():
    return _state["lang"]


def t(key, **kw):
    s = T[_state["lang"]].get(key) or T["en"].get(key) or key
    if kw:
        try:
            s = s.format(**kw)
        except Exception:
            pass
    return s


def autodetect():
    for var in ("LC_ALL", "LC_MESSAGES", "LANG"):
        v = os.environ.get(var, "")
        if v:
            code = v.split(".")[0][:2].lower()
            if code in ("pt", "zh", "es", "ru", "en"):
                return code
    return "en"
